import json, random, sys, time
sys.path.insert(0,'/workspace/tmp'); sys.path.insert(0,'/workspace/submission')
import ref, main as impl

def measure(atoms, services, maxlen=14, n=10):
    req = {'services':services,'rules':[{'action':'allow','when':{'op':'contains','path':list(p)}} for p in atoms],'queries':[[],[services[0]]]}
    got = impl.process(json.dumps(req).encode())
    if got.startswith('{"ok":false'):
        return got, None
    out = json.loads(got)
    return 'ok', len(out['dfa']['next'])

rng = random.Random(7)
for L in (10, 12, 14, 16):
    atoms = [tuple(rng.choice(['a','b']) for _ in range(L)) for _ in range(10)]
    t0=time.time(); r = measure(atoms, ['a','b']); t1=time.time()
    print('contains len', L, r, '%.2fs'%(t1-t0))
# with match atoms (chains + fail) -> product can be bigger?
for L in (8, 10, 12, 14, 16):
    atoms = [tuple(rng.choice(['a','b']) for _ in range(L)) for _ in range(10)]
    t0=time.time(); r = measure(atoms, ['a','b'], 14); print('match len', L, r, '%.2fs'%(time.time()-t0))
    req_m = {'services':['a','b'],'rules':[{'action':'allow','when':{'op':'match','path':list(p)}} for p in atoms],'queries':[]}
    t0=time.time(); rr = impl.process(json.dumps(req_m).encode()); print('  match:', rr[:40], '%.2fs'%(time.time()-t0))
EOF
